// c_submit
fn match0(s: &S, a0: &Job) -> Result<Option<(Job, )>, StepError> {
    let v_j = a0.clone();
    if !((i128::from((v_j.clone()).0) == s.nj.clone())) {
        return Ok(None);
    }
    Ok(Some((v_j, )))
}

fn fire0(s: &mut S, env: (Job, )) -> Result<(), StepError> {
    let (v_j, ) = env;
    let n_nj = rt::add(s.nj.clone(), 1i128)?;
    let mut o_st = Ov::over(&s.st);
    o_st.set(v_j.clone(), JSt::QUEUED);
    let w_st = o_st.writes();
    let mut o_entered = Ov::over(&s.entered);
    o_entered.set(JSt::QUEUED, rt::add(((&s.entered)).get(&JSt::QUEUED), 1i128)?);
    let w_entered = o_entered.writes();
    let r_Q_0 = rt::insert(BTreeSet::new(), v_j.clone());
    for (k, v) in w_st {
        s.st.set(k, v);
    }
    for (k, v) in w_entered {
        s.entered.set(k, rt::fit(v, 0, 4294967295, "entered")?);
    }
    s.nj = rt::fit(n_nj, 0, 4294967295, "nj")?;
    for x in r_Q_0 {
        let k = x.clone();
        if s.Q.insert(x) {
            let _ = k;
        }
    }
    Ok(())
}

// c_finished
fn match1(s: &S, a0: &Job) -> Result<Option<(Job, )>, StepError> {
    let v_j = a0.clone();
    if !((((&s.st)).get(&v_j.clone()) == JSt::RUNNING)) {
        return Ok(None);
    }
    Ok(Some((v_j, )))
}

fn fire1(s: &mut S, env: (Job, )) -> Result<(), StepError> {
    let (v_j, ) = env;
    let mut o_st = Ov::over(&s.st);
    o_st.set(v_j.clone(), JSt::DONE);
    let w_st = o_st.writes();
    let n_slots = rt::add(s.slots.clone(), 1i128)?;
    let mut o_entered = Ov::over(&s.entered);
    o_entered.set(JSt::DONE, rt::add(((&s.entered)).get(&JSt::DONE), 1i128)?);
    let w_entered = o_entered.writes();
    for (k, v) in w_st {
        s.st.set(k, v);
    }
    for (k, v) in w_entered {
        s.entered.set(k, rt::fit(v, 0, 4294967295, "entered")?);
    }
    s.slots = rt::fit(n_slots, 0, 4294967295, "slots")?;
    Ok(())
}

