/// Checks the action record against the unrefined Core (docs/spec.md §3.8.9).
#[derive(Debug)]
pub struct Acceptor {
    s: S,
}

impl Acceptor {
    pub fn new(config: Config) -> Result<Acceptor, StepError> {
        Ok(Acceptor { s: initial(&config)? })
    }

    /// The state, for tests.
    pub fn state(&self) -> &S {
        &self.s
    }

    /// The state, for tests that start from another initial state.
    #[doc(hidden)]
    pub fn state_mut(&mut self) -> &mut S {
        &mut self.s
    }

    pub fn accept(&mut self, entry: &Entry) -> Result<(), Reject> {
        match entry {
            Entry::Action(Action::GiveUp(a0)) => {
                let e3 = match3(&self.s, a0).map_err(Reject::Step)?;
                let found = [e3.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e3 {
                    return fire3(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Action(Action::Retry(a0)) => {
                let e4 = match4(&self.s, a0).map_err(Reject::Step)?;
                let found = [e4.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e4 {
                    return fire4(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Action(Action::Start(a0)) => {
                let e5 = match5(&self.s, a0).map_err(Reject::Step)?;
                let found = [e5.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e5 {
                    return fire5(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Event(Event::Crashed(a0)) => {
                let e2 = match2(&self.s, a0).map_err(Reject::Step)?;
                let found = [e2.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e2 {
                    return fire2(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Event(Event::Finished(a0)) => {
                let e1 = match1(&self.s, a0).map_err(Reject::Step)?;
                let found = [e1.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e1 {
                    return fire1(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Event(Event::Submit(a0)) => {
                let e0 = match0(&self.s, a0).map_err(Reject::Step)?;
                let found = [e0.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e0 {
                    return fire0(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
        }
    }
}

fn enc_JSt(v: &JSt, out: &mut Vec<u8>) {
    codec::nat(match v {
        JSt::FREE => 0,
        JSt::QUEUED => 1,
        JSt::RUNNING => 2,
        JSt::FAILED => 3,
        JSt::DONE => 4,
        JSt::GAVEUP => 5,
    }, out);
}

fn dec_JSt(r: &mut codec::Rd<'_>) -> Result<JSt, DecodeError> {
    match r.nat()? {
        0 => Ok(JSt::FREE),
        1 => Ok(JSt::QUEUED),
        2 => Ok(JSt::RUNNING),
        3 => Ok(JSt::FAILED),
        4 => Ok(JSt::DONE),
        5 => Ok(JSt::GAVEUP),
        _ => Err(DecodeError("a constructor index")),
    }
}

/// The bytes of an entry (docs/spec.md §3.8.10).
pub fn encode(entry: &Entry, out: &mut Vec<u8>) {
    match entry {
        Entry::Event(Event::Crashed(a0)) => {
            out.push(0);
            codec::nat(0, out);
            codec::nat(i128::from((a0).0), out);
        }
        Entry::Event(Event::Finished(a0)) => {
            out.push(0);
            codec::nat(1, out);
            codec::nat(i128::from((a0).0), out);
        }
        Entry::Event(Event::Submit(a0)) => {
            out.push(0);
            codec::nat(2, out);
            codec::nat(i128::from((a0).0), out);
        }
        Entry::Action(Action::GiveUp(a0)) => {
            out.push(1);
            codec::nat(0, out);
            codec::nat(i128::from((a0).0), out);
        }
        Entry::Action(Action::Retry(a0)) => {
            out.push(1);
            codec::nat(1, out);
            codec::nat(i128::from((a0).0), out);
        }
        Entry::Action(Action::Start(a0)) => {
            out.push(1);
            codec::nat(2, out);
            codec::nat(i128::from((a0).0), out);
        }
    }
}

/// The entry of some bytes (§3.8.10).
pub fn decode(bytes: &[u8]) -> Result<Entry, DecodeError> {
    let mut r = codec::Rd { b: bytes, p: 0 };
    let r = &mut r;
    let side = r.byte()?;
    let code = r.nat()?;
    let e = match (side, code) {
        (0, 0) => Entry::Event(Event::Crashed(Job(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (0, 1) => Entry::Event(Event::Finished(Job(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (0, 2) => Entry::Event(Event::Submit(Job(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (1, 0) => Entry::Action(Action::GiveUp(Job(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (1, 1) => Entry::Action(Action::Retry(Job(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (1, 2) => Entry::Action(Action::Start(Job(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        _ => return Err(DecodeError("a label")),
    };
    if !r.done() {
        return Err(DecodeError("trailing bytes"));
    }
    Ok(e)
}

fn ixmem_retryable(s: &S, v: Job) -> Result<bool, StepError> {
    Ok(((((&s.st)).get(&v.clone()) == JSt::FAILED) && (((&s.tries)).get(&v.clone()) < m_retries()?)))
}

fn ixbound_retryable(s: &S) -> Result<i128, StepError> {
    Ok(s.nj.clone())
}

fn ixfirst_retryable(s: &S) -> Result<Job, StepError> {
    s.ix_retryable.front(0).map(|(_, v)| Job(v)).ok_or(StepError::Undefined("first(retryable)"))
}

fn ixsome_retryable(s: &S) -> Result<bool, StepError> {
    Ok(s.ix_retryable.front(0).is_some())
}

fn ixrefresh_retryable(s: &mut S, v: u32) -> Result<(), StepError> {
    let n = Job(v);
    if ixmem_retryable(s, n)? {
        let (c, k) = (0, 0);
        s.ix_retryable.refresh(v, true, c, k)
    } else {
        s.ix_retryable.refresh(v, false, 0, 0)
    }
}

fn ixmem_spent(s: &S, v: Job) -> Result<bool, StepError> {
    Ok(((((&s.st)).get(&v.clone()) == JSt::FAILED) && (((&s.tries)).get(&v.clone()) >= m_retries()?)))
}

fn ixbound_spent(s: &S) -> Result<i128, StepError> {
    Ok(s.nj.clone())
}

fn ixfirst_spent(s: &S) -> Result<Job, StepError> {
    s.ix_spent.front(0).map(|(_, v)| Job(v)).ok_or(StepError::Undefined("first(spent)"))
}

fn ixsome_spent(s: &S) -> Result<bool, StepError> {
    Ok(s.ix_spent.front(0).is_some())
}

fn ixrefresh_spent(s: &mut S, v: u32) -> Result<(), StepError> {
    let n = Job(v);
    if ixmem_spent(s, n)? {
        let (c, k) = (0, 0);
        s.ix_spent.refresh(v, true, c, k)
    } else {
        s.ix_spent.refresh(v, false, 0, 0)
    }
}

/// The indexes refreshed at the ids the last summand wrote (docs/spec.md §3.8.3).
fn refresh(s: &mut S) -> Result<(), StepError> {
    let d = std::mem::take(&mut s.dirty_Job);
    let mut seen = BTreeSet::new();
    for v in d {
        if !seen.insert(v) {
            continue;
        }
        ixrefresh_retryable(s, v)?;
        ixrefresh_spent(s, v)?;
    }
    Ok(())
}

fn stepper_init(s: &mut S) -> Result<(), StepError> {
    s.ix_retryable = Ix::new(3, 1);
    s.ix_spent = Ix::new(0, 1);
    let b = u32::try_from(ixbound_retryable(s)?).map_err(|_| StepError::Overflow("bound"))?;
    for v in 0..b {
        ixrefresh_retryable(s, v)?;
    }
    let b = u32::try_from(ixbound_spent(s)?).map_err(|_| StepError::Overflow("bound"))?;
    for v in 0..b {
        ixrefresh_spent(s, v)?;
    }
    Ok(())
}

